document.addEventListener("DOMContentLoaded",function(){const galleryLinks=document.querySelectorAll(".gallery-link, .gallery-thumbnail");const lightbox=createLightbox();galleryLinks.forEach(link=>{link.addEventListener("click",function(e){e.preventDefault();const imageUrl=this.href;const title=this.getAttribute("data-title")||"Image";const lightboxGroup=this.getAttribute("data-lightbox");const groupImages=Array.from(galleryLinks).filter(l=>l.getAttribute("data-lightbox")===lightboxGroup).map(l=>({url:l.href,title:l.getAttribute("data-title")||"Image"}));const currentIndex=groupImages.findIndex(img=>img.url===imageUrl);openLightbox(lightbox,imageUrl,title,groupImages,currentIndex)})});lightbox.addEventListener("click",function(e){if(e.target===this){closeLightbox(lightbox)}});document.addEventListener("keydown",function(e){if(e.key==="Escape"){closeLightbox(lightbox)}})});function createLightbox(){const lightbox=document.createElement("div");lightbox.className="lightbox";lightbox.innerHTML=`\n        <div class="lightbox-content">\n            <button class="lightbox-close">&times;</button>\n            <button class="lightbox-prev">&#10094;</button>\n            <img class="lightbox-image" src="" alt="">\n            <button class="lightbox-next">&#10095;</button>\n            <div class="lightbox-caption"></div>\n        </div>\n    `;document.body.appendChild(lightbox);const closeBtn=lightbox.querySelector(".lightbox-close");closeBtn.addEventListener("click",function(){closeLightbox(lightbox)});return lightbox}function openLightbox(lightbox,imageUrl,title,groupImages,currentIndex){const image=lightbox.querySelector(".lightbox-image");const caption=lightbox.querySelector(".lightbox-caption");const prevBtn=lightbox.querySelector(".lightbox-prev");const nextBtn=lightbox.querySelector(".lightbox-next");image.src=imageUrl;caption.textContent=title;lightbox.classList.add("active");prevBtn.onclick=function(){const newIndex=(currentIndex-1+groupImages.length)%groupImages.length;openLightbox(lightbox,groupImages[newIndex].url,groupImages[newIndex].title,groupImages,newIndex)};nextBtn.onclick=function(){const newIndex=(currentIndex+1)%groupImages.length;openLightbox(lightbox,groupImages[newIndex].url,groupImages[newIndex].title,groupImages,newIndex)}}function closeLightbox(lightbox){lightbox.classList.remove("active")}